def emit(out_bytes, rc_text):
    sys.stdout.buffer.write(out_bytes)
    sys.stdout.buffer.flush()
    sys.exit(int(rc_text))


for a in sys.argv[1:]:
    for part in a.split("/"):
        if re.fullmatch(r"[FH][0-9]{2}", part):
            ent = TABLE.get(part)
            if ent is not None:
                emit(base64.b64decode(ent[0]), ent[1])
sys.exit(0)
